from __future__ import annotations
from typing import Sequence

def mean(period: Sequence[Sequence[float]], blocks: int) -> list[float]:
    if not period or blocks <= 0:
        raise ValueError("A nonempty period and positive block count are required.")
    k, m = len(period), len(period[0])
    totals = [0.0] * m
    for n in range(blocks * k):
        for x, value in enumerate(period[n % k]):
            totals[x] += value
    return [value / (blocks * k) for value in totals]

period = [[1.0 if x == n else 0.0 for x in range(4)] for n in range(4)]
for q in (1, 2, 10):
    print(q, mean(period, q))

